sys_ux_screen_condition.script:
(function activeCallComponentScriptCondition(params) {
    var sysId = params.sysId;
    var table = params.table;
    if (!gs.nil(sysId) && !gs.nil(table)) {
        var input = {
            "table": table,
            "sysId": sysId
        };
        return new ICCHelper().canShowActiveCallComponent(input);
    }
    return false;
})(inputProperties);
